SELECT * FROM logs WHERE (Image LIKE '%\\schtasks.exe' ESCAPE '\' AND CommandLine LIKE '% /create %' ESCAPE '\') AND (NOT COALESCE((User LIKE '%AUTHORI%' ESCAPE '\' OR User LIKE '%AUTORI%' ESCAPE '\'), 0)) AND (NOT COALESCE(((ParentImage LIKE 'C:\\Program Files\\Microsoft Office\\root\\integration\\integrator.exe' ESCAPE '\' OR ParentImage LIKE 'C:\\Program Files (x86)\\Microsoft Office\\root\\integration\\integrator.exe' ESCAPE '\') AND (Image LIKE 'C:\\Windows\\System32\\schtasks.exe' ESCAPE '\' OR Image LIKE 'C:\\Windows\\SysWOW64\\schtasks.exe' ESCAPE '\') AND CommandLine LIKE '%Microsoft\\Office\\Office Performance Monitor%' ESCAPE '\'), 0))
